package redirectproxy

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"strconv"
	"strings"
	"time"
)

const (
	maxClockSkew  = 30 * time.Second
	servicePrefix = "/api/v2/cloud/redirect"
)

// getHMACSecret loads the HMAC secret from the environment instead of
// hardcoding it in the source. Returns an empty byte slice if unset, which
// causes signature validation to fail closed.
func getHMACSecret() []byte {
	return []byte(os.Getenv("REDIRECT_HMAC_SECRET"))
}

// AllowedHosts defines the set of permitted redirect destinations
var AllowedHosts = map[string]bool{
	"console.cloud.internal":   true,
	"dashboard.cloud.internal": true,
	"auth.cloud.internal":      true,
	"cdn.cloud.internal":       true,
	"static.cloud.internal":    true,
}

// RedirectRequest represents a signed redirect from the service mesh
type RedirectRequest struct {
	Target    string
	Timestamp int64
	Signature string
	ServiceID string
}

// ValidateHMAC checks the HMAC signature of the redirect request
func ValidateHMAC(target string, timestamp int64, serviceID string, signature string) bool {
	secret := getHMACSecret()
	if len(secret) == 0 {
		// Fail closed if no secret is configured
		return false
	}
	mac := hmac.New(sha256.New, secret)
	message := fmt.Sprintf("%s|%d|%s", target, timestamp, serviceID)
	mac.Write([]byte(message))
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(signature))
}

// NormalizeRedirectURL processes the target URL through the reverse proxy
// normalization layer, handling service mesh internal routing
func NormalizeRedirectURL(rawTarget string) (*url.URL, error) {
	// First pass: decode any proxy-layer encoding
	decoded, err := url.QueryUnescape(rawTarget)
	if err != nil {
		decoded = rawTarget
	}

	// Parse the URL for validation
	parsed, err := url.Parse(decoded)
	if err != nil {
		return nil, fmt.Errorf("invalid redirect target: %w", err)
	}

	// If scheme is empty, treat as relative path within the mesh
	if parsed.Scheme == "" {
		parsed.Scheme = "https"
		parsed.Host = "console.cloud.internal"
	}

	return parsed, nil
}

// IsHostAllowed validates the target host against the allowlist
// Uses the parsed URL's Hostname() to strip port numbers
func IsHostAllowed(u *url.URL) bool {
	host := u.Hostname()
	// Check exact match
	if AllowedHosts[host] {
		return true
	}
	// Check if it's a subdomain of an allowed host
	for allowed := range AllowedHosts {
		if strings.HasSuffix(host, "."+allowed) {
			return true
		}
	}
	return false
}

// HandleRedirect processes authenticated redirect requests from the service mesh
func HandleRedirect(w http.ResponseWriter, r *http.Request) {
	// Extract redirect parameters
	target := r.URL.Query().Get("target")
	sig := r.URL.Query().Get("sig")
	serviceID := r.Header.Get("X-Service-ID")
	timestampStr := r.URL.Query().Get("ts")

	if target == "" || sig == "" || serviceID == "" || timestampStr == "" {
		http.Error(w, "missing required parameters", http.StatusBadRequest)
		return
	}

	// Parse timestamp, rejecting malformed input
	timestamp, err := strconv.ParseInt(timestampStr, 10, 64)
	if err != nil {
		http.Error(w, "invalid timestamp", http.StatusBadRequest)
		return
	}

	// Validate clock skew
	now := time.Now().Unix()
	if abs(now-timestamp) > int64(maxClockSkew.Seconds()) {
		http.Error(w, "request expired", http.StatusForbidden)
		return
	}

	// Validate HMAC signature
	if !ValidateHMAC(target, timestamp, serviceID, sig) {
		http.Error(w, "invalid signature", http.StatusForbidden)
		return
	}

	// Normalize the URL through the proxy layer
	normalized, err := NormalizeRedirectURL(target)
	if err != nil {
		http.Error(w, "invalid target URL", http.StatusBadRequest)
		return
	}

	// Validate the host is in our allowlist
	if !IsHostAllowed(normalized) {
		http.Error(w, "redirect target not allowed", http.StatusForbidden)
		return
	}

	// Use the already-validated normalized URL for the redirect
	http.Redirect(w, r, normalized.String(), http.StatusFound)
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

// RegisterRoutes sets up the redirect handler on the mux
func RegisterRoutes(mux *http.ServeMux) {
	mux.HandleFunc(servicePrefix, HandleRedirect)
}
